from pathlib import Path
import subprocess,hashlib,os,json,time
work=Path(__file__).resolve().parent;root=work.parent
compiler=root.parent/'d9-performance43/.tmp-perf43/install/bin/mylang'
env={k:v for k,v in os.environ.items() if not k.startswith('MYLANG_')};env['TMPDIR']=str(work/'tmp')
result={}
for side in ['hoist-before','hoist']:
 for backend in ['llvm']:
  source=work/side;binary=work/f'lox-{side}-{backend}'
  cmd=[str(compiler),'build','main.my','--project','--mode','ReleaseFast','--backend',backend,'--llvm-opt','3','--lto','--cache-dir',str(work/'guest-cache'),'-o',str(binary),'--value-semantics']
  print('BUILD',side,backend,flush=True)
  done=subprocess.run(cmd,cwd=source,env=env,capture_output=True,text=True)
  result[side+'-'+backend]={'command':cmd,'status':done.returncode,'stderr':done.stderr,'compiler_sha256':hashlib.sha256(compiler.read_bytes()).hexdigest(),'source_sha256':{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(source.glob('*.my'))}}
  if done.returncode: print(done.stderr,flush=True)
  else:result[side+'-'+backend]['binary_sha256']=hashlib.sha256(binary.read_bytes()).hexdigest()
  (work/'hoist-builds.json').write_text(json.dumps(result,indent=2)+'\n')
  if done.returncode:raise SystemExit(done.returncode)
  print('PASS',side,backend,flush=True)
